import sys; sys.path.insert(0,'/tmp/g6v2')
import nnbase
nnbase.OUTS={'تحدّث':["GC-SP1.G{y}","GC-SP3.G{y}","GC-GR1.G{y}"],'استماع':["GC-LI1.G{y}","GC-LI2.G{y}","GC-GR1.G{y}"],'قراءة':["GC-RE1.G{y}","GC-TR1.G{y}","GC-GR1.G{y}"],'كتابة':["GC-WR1.G{y}","GC-TR2.G{y}","GC-GR1.G{y}"]}
from nnbase import N
SP=[]
def V(s):
    out=[]
    for it in s.split(";"):
        w,m,e,en=[x.strip() for x in it.split("|")]; out.append((w,m,e,en))
    return out
def G(code,U,title,emo,skill,topic,vocab,frames,model,qbox,task,real,chk,idea,th):
    y=int(code.split('-')[1][1:])
    S=N(code,U,title,"GCSE 1AA0",emo,skill,topic,V(vocab),frames,model,qbox,task,real,chk,idea,[1,"العربية جسر بين الثقافات، والإمارات ملتقاها."],"الدرس السابق","الدرس القادم")
    S['outs']=[o.format(y=y) for o in nnbase.OUTS.get(skill,nnbase.OUTS['تحدّث'])]+[f"GC-{th}.G{y}"]
    S['track']='gcse'
    SP.append(S)
